query:
SELECT DISTINCT ?root ?item ?en ?zh ?description ?kind WHERE {
      hint:Query hint:optimizer "None".
      { SELECT DISTINCT ?root ?item ?en ?zh WHERE {
        { VALUES ?root { wd:Q11376 wd:Q161254 wd:Q205805 wd:Q1071013 wd:Q900634 wd:Q1111 wd:Q29996 wd:Q841798 wd:Q43116 wd:Q5380792 wd:Q11402 wd:Q11652 wd:Q104934 wd:Q179388 wd:Q1061524 wd:Q177831 wd:Q11423 wd:Q41273 wd:Q639 wd:Q173227 } ?item wdt:P31 ?root }
        UNION { VALUES ?root { wd:Q11376 wd:Q161254 wd:Q205805 wd:Q1071013 wd:Q900634 wd:Q1111 wd:Q29996 wd:Q841798 wd:Q43116 wd:Q5380792 wd:Q11402 wd:Q11652 wd:Q104934 wd:Q179388 wd:Q1061524 wd:Q177831 wd:Q11423 wd:Q41273 wd:Q639 wd:Q173227 } ?item wdt:P279 ?root }
        UNION { VALUES ?root { wd:Q11376 wd:Q161254 wd:Q205805 wd:Q1071013 wd:Q900634 wd:Q1111 wd:Q29996 wd:Q841798 wd:Q43116 wd:Q5380792 wd:Q11402 wd:Q11652 wd:Q104934 wd:Q179388 wd:Q1061524 wd:Q177831 wd:Q11423 wd:Q41273 wd:Q639 wd:Q173227 } BIND(?root AS ?item) }
        ?item rdfs:label ?en, ?zh.
        FILTER(LANG(?en)="en" && LANG(?zh) IN ("zh-hans", "zh-cn", "zh", "zh-tw", "zh-hant"))
        FILTER NOT EXISTS { ?item wdt:P31 wd:Q5 }
      } LIMIT 20000 }
      OPTIONAL { ?item schema:description ?description. FILTER(LANG(?description)="en") }
      OPTIONAL { ?item wdt:P31 ?kind }
    }
